import{_ as h,o as t,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"&quot;Mục tiêu cuối cùng không chỉ là thi đỗ&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"mental-models/muc-tieu-cuoi.md","filePath":"mental-models/muc-tieu-cuoi.md"}'),c={name:"mental-models/muc-tieu-cuoi.md"};function u(g,n,o,r,e,m){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="quot-muc-tieu-cuoi-cung-khong-chi-la-thi-đo-quot" tabindex="-1">&quot;Mục tiêu cuối cùng không chỉ là thi đỗ&quot; <a class="header-anchor" href="#quot-muc-tieu-cuoi-cung-khong-chi-la-thi-đo-quot" aria-label="Permalink to &quot;&amp;quot;Mục tiêu cuối cùng không chỉ là thi đỗ&amp;quot;&quot;">​</a></h1><p>Trên trang này# &quot;Mục tiêu cuối cùng không chỉ là thi đỗ&quot; <a href="#muc-tieu-cuoi-cung-khong-chi-la-thi-đo">​</a> Thi đỗ là một cánh cửa. Cửa mở ra rồi thì vẫn còn nhiều năm phía sau, và những năm đó cần những thứ mà việc luyện thi không xây được.</p><h2 id="chuyen-xay-ra-sau-khi-cua-mo-​" tabindex="-1">Chuyện xảy ra sau khi cửa mở <a href="#chuyen-xay-ra-sau-khi-cua-mo">​</a> <a class="header-anchor" href="#chuyen-xay-ra-sau-khi-cua-mo-​" aria-label="Permalink to &quot;Chuyện xảy ra sau khi cửa mở [​](#chuyen-xay-ra-sau-khi-cua-mo)&quot;">​</a></h2><p>Hai kịch bản quen thuộc, cả hai đều là hệ quả của việc đặt kỳ thi làm đích cuối: <strong>Đỗ rồi mất phương hướng.</strong> Một học sinh dồn ba năm cho một mục tiêu duy nhất, đỗ, rồi sụp trong học kỳ đầu tiên. Không phải vì không đủ giỏi — mà vì suốt ba năm không ai hỏi &quot;rồi sau đó thì sao&quot;, và giờ không có câu trả lời nào. <strong>Đỗ nhưng nền hổng.</strong> Luyện đúng dạng đề thì qua được kỳ thi, nhưng chương trình bậc trên đòi hỏi nền rộng hơn nhiều so với thứ đề thi kiểm tra. Lỗ hổng vốn được che bởi kỹ năng làm bài giờ lộ ra — ở một môi trường khó hơn nhiều. Cả hai đều là hệ quả trực tiếp của việc tối ưu cho một thời điểm thay vì cho một quá trình.</p><h2 id="thu-van-con-gia-tri-sau-ky-thi-​" tabindex="-1">Thứ vẫn còn giá trị sau kỳ thi <a href="#thu-van-con-gia-tri-sau-ky-thi">​</a> <a class="header-anchor" href="#thu-van-con-gia-tri-sau-ky-thi-​" aria-label="Permalink to &quot;Thứ vẫn còn giá trị sau kỳ thi [​](#thu-van-con-gia-tri-sau-ky-thi)&quot;">​</a></h2><p>Thứ luyện thi xây đượcThứ vẫn còn sau đóThuộc dạng đềHiểu nguyên tắcTốc độ làm bàiKhả năng tự học thứ mớiKỹ thuật loại trừBiết mình không hiểu chỗ nàoChịu được áp lực ngắn hạnBền bỉ với việc dài hạnKết quả một ngàyThói quen làm việcCột trái không vô giá trị — nó thật sự giúp đỗ, và đỗ là chuyện quan trọng. Nhưng nếu ba năm chỉ xây được cột trái, thì cái giá phải trả nằm ở những năm sau. Điều đáng mừng: hai cột không loại trừ nhau. Một learner có nền vững thường thi tốt hơn một learner chỉ luyện dạng — đặc biệt khi đề đổi cách hỏi, điều xảy ra thường xuyên hơn người ta nghĩ.</p><h2 id="ba-cau-hoi-mo-rong-khung-nhin-​" tabindex="-1">Ba câu hỏi mở rộng khung nhìn <a href="#ba-cau-hoi-mo-rong-khung-nhin">​</a> <a class="header-anchor" href="#ba-cau-hoi-mo-rong-khung-nhin-​" aria-label="Permalink to &quot;Ba câu hỏi mở rộng khung nhìn [​](#ba-cau-hoi-mo-rong-khung-nhin)&quot;">​</a></h2><p><strong>&quot;Sau khi đỗ thì sao?&quot;</strong> Hỏi câu này <em>trước</em> kỳ thi, không phải sau. Nếu không ai trả lời được, đó là dấu hiệu kỳ thi đang chiếm quá nhiều chỗ trong câu chuyện của gia đình. <strong>&quot;Nếu trượt thì còn lại gì?&quot;</strong> Một gia đình chỉ có một mục tiêu sẽ mất tất cả nếu trượt. Một gia đình có <a href="/portrait/">Portrait</a> vẫn còn chín mảng khác nguyên vẹn — và đứa trẻ vẫn còn nhiều cách để nhìn về bản thân nó. <strong>&quot;Trong ba năm này, con trở thành người thế nào?&quot;</strong> Ba năm ôn thi cũng là ba năm của một tuổi thiếu niên. Đứa trẻ bước ra khỏi đó là ai — bên cạnh chuyện đỗ hay trượt?</p><h2 id="khong-phai-la-đung-coi-trong-ky-thi-​" tabindex="-1">Không phải là &quot;đừng coi trọng kỳ thi&quot; <a href="#khong-phai-la-đung-coi-trong-ky-thi">​</a> <a class="header-anchor" href="#khong-phai-la-đung-coi-trong-ky-thi-​" aria-label="Permalink to &quot;Không phải là &quot;đừng coi trọng kỳ thi&quot; [​](#khong-phai-la-đung-coi-trong-ky-thi)&quot;">​</a></h2><p>Nemo12 chuẩn bị cho kỳ thi rất nghiêm túc. Cánh cửa là có thật; trường tốt tạo khác biệt thật; và một gia đình lo lắng về kỳ thi là một gia đình đang quan tâm đúng chỗ. Đề nghị ở đây chỉ là về <strong>vị trí</strong>: kỳ thi là một cột mốc quan trọng trên đường, không phải điểm cuối của con đường. Sự khác biệt này quyết định cách chuẩn bị. Nếu kỳ thi là đích cuốiMọi thứ không có trong đề đều là thứ làm mất tập trung. Tối ưu ngắn hạn luôn thắng. Sau ngày thi là khoảng trống. Nếu kỳ thi là một cột mốcVẫn ôn nghiêm túc, nhưng không hy sinh nền. Vẫn giữ những thứ khác trong đời con. Sau ngày thi vẫn còn đường đi tiếp.</p><h2 id="nemo12-giu-đieu-nay-the-nao-​" tabindex="-1">Nemo12 giữ điều này thế nào <a href="#nemo12-giu-đieu-nay-the-nao">​</a> <a class="header-anchor" href="#nemo12-giu-đieu-nay-the-nao-​" aria-label="Permalink to &quot;Nemo12 giữ điều này thế nào [​](#nemo12-giu-đieu-nay-the-nao)&quot;">​</a></h2><p><strong>Không hy sinh nền để lấy điểm ngắn hạn.</strong> Nếu một mắt xích nền quan trọng đang hổng, nó vẫn được ưu tiên — kể cả trong giai đoạn ôn thi — vì cái giá của việc bỏ qua nó sẽ đến sau kỳ thi. <strong>Mục tiêu học thuật là một trong mười mảng.</strong> Portrait giữ chín mảng còn lại hiện diện, ngay cả trong những tháng căng nhất. <strong>&quot;Nghỉ&quot; là một đề xuất hợp lệ.</strong> Một hệ thống chỉ tối ưu cho ngày thi sẽ không bao giờ khuyên nghỉ. <a href="/decisions/hoc-test-nghi">Xem vì sao →</a><strong>Milestone không chỉ là kỳ thi.</strong> Tự lên kế hoạch học, hoàn thành một dự án, dám hỏi khi không hiểu — những mốc này được theo dõi ngang hàng với các mốc điểm số. <a href="/portrait/milestone">Xem milestone →</a> Một cách kiểm tra Nhìn vào những gì gia đình bạn nói chuyện trong ba tháng qua. Nếu gần như toàn bộ xoay quanh điểm số và kỳ thi, thì với con, đó đang là toàn bộ ý nghĩa của việc lớn lên. Không phải vì bạn nói vậy. Vì đó là thứ duy nhất được nói tới. Đỗ là một cánh cửa. Câu hỏi quan trọng hơn là: đứa trẻ bước qua cánh cửa đó là ai, và còn muốn đi tiếp không? <a href="/mental-models/portrait-vs-kpi">Portrait quan trọng hơn danh sách KPI →</a></p>',12)])])}const k=h(c,[["render",u]]);export{s as __pageData,k as default};
